#include "MapMetrics.h"
#include "SimCore.h"
#include "SimArchive.h"
namespace CoISim {
FMetricValue MetricValue(const FDayMetrics& Day,const FString& Region,const FString& Good,EMapMetric Kind){FMetricValue V;if(!Day.Complete)return V;const auto* R=Day.Rows.FindByPredicate([&](const FDayMetric& M){return M.RegionId==Region&&M.GoodId==Good;});if(!R)return V;if(Kind==EMapMetric::Price){V.TradeKg=R->TradeKg;V.TradeCents=R->TradeCents;if(R->TradeKg>0){V.Availability=EMetricAvailability::Value;V.Value=(double)R->TradeCents/R->TradeKg;}return V;}V.Wanted=Kind==EMapMetric::Households?R->HouseholdWantedKg:R->InputWantedKg;V.Used=Kind==EMapMetric::Households?R->HouseholdUsedKg:R->InputUsedKg;V.Availability=V.Wanted?EMetricAvailability::Value:EMetricAvailability::NoNeed;V.Value=V.Wanted?100.*V.Used/V.Wanted:0;return V;}
FLinearColor MetricColor(const FMetricValue& V,EMapMetric Kind,const FGoodDef& Good){if(V.Availability==EMetricAvailability::Missing)return {.28f,.30f,.32f};if(V.Availability==EMetricAvailability::NoNeed)return {.30f,.36f,.40f};double X=Kind==EMapMetric::Price?(V.Value-Good.MapPriceLowCents)/(Good.MapPriceHighCents-Good.MapPriceLowCents):V.Value/100.;X=FMath::Clamp(X,0.,1.);const FLinearColor Red(.72f,.09f,.055f),Yellow(.76f,.58f,.06f),Green(.055f,.55f,.19f);FLinearColor Low=Kind==EMapMetric::Price?Green:Red,High=Kind==EMapMetric::Price?Red:Green;return X<=.5?FMath::Lerp(Low,Yellow,(float)(X*2)):FMath::Lerp(Yellow,High,(float)((X-.5)*2));}
void FSimulation::BeginDayMetrics(int64 Day){State.CurrentDayMetrics=FDayMetrics();State.CurrentDayMetrics.Day=Day;for(const auto& R:Scenario.Definitions.Regions)for(const auto& G:Scenario.Definitions.Goods){FDayMetric M;M.Id=R.Id+TEXT("|")+G.Id;M.RegionId=R.Id;M.GoodId=G.Id;State.CurrentDayMetrics.Rows.Add(M);}}
FDayMetric& FSimulation::DayMetric(const FString& Region,const FString& Good){auto* M=Find(State.CurrentDayMetrics.Rows,Region+TEXT("|")+Good);check(M);return *M;}
void FSimulation::FinishDayMetrics(int64 Step){State.CurrentDayMetrics.Complete=true;State.CurrentDayMetrics.CompletedStep=Step;State.LastDayMetrics=State.CurrentDayMetrics;BeginDayMetrics(State.CurrentDayMetrics.Day+1);}
}
